    String stripped = trimmed.replaceAll("[\\s\\-()]", "");
    if (hasCountryCode) {
        stripped = stripped.substring(1);
    }
    if (!stripped.matches("\\d+")) {
        return null;
    }
    String digits;
    if (hasCountryCode) {
        digits = stripped;
    } else {
        if (stripped.startsWith("0")) {
            stripped = stripped.substring(1);
        }
        digits = "61" + stripped;
    }
    if (digits.length() < 8 || digits.length() > 15) {
        return null;
    }
    if (!hasValidNationalNumberLength(digits)) {
        return null;
    }
    return "+" + digits;
}

